class Solution {
    public int longestValidParentheses(String s) {
        int n = s.length();
        for (int len = n - (n % 2); len >= 2; len -= 2) {
            for (int start = 0; start + len <= n; start++) {
                if (isValid(s, start, start + len - 1)) return len;
            }
        }
        return 0;
    }

    private boolean isValid(String s, int start, int end) {
        int balance = 0;
        for (int i = start; i <= end; i++) {
            if (s.charAt(i) == 40) balance++;
            else balance--;
            if (balance < 0) return false;
        }
        return balance == 0;
    }
}

import java.util.*;

class Solution {
    public int longestValidParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);
        int best = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 40) {
                stack.push(i);
            } else {
                stack.pop();
                if (stack.isEmpty()) stack.push(i);
                else best = Math.max(best, i - stack.peek());
            }
        }
        return best;
    }
}

class Solution {
    public int longestValidParentheses(String s) {
        int best = 0;
        int left = 0;
        int right = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 40) left++;
            else right++;
            if (left == right) best = Math.max(best, 2 * right);
            else if (right > left) {
                left = 0;
                right = 0;
            }
        }

        left = 0;
        right = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == 40) left++;
            else right++;
            if (left == right) best = Math.max(best, 2 * left);
            else if (left > right) {
                left = 0;
                right = 0;
            }
        }
        return best;
    }
}
